--liquibase formatted sql
--changeset gratilo:003-payment-url-pool
ALTER TABLE user_mgmt.users ADD COLUMN payment_url_path VARCHAR(120);
CREATE UNIQUE INDEX IF NOT EXISTS users_payment_url_path_unique ON user_mgmt.users(payment_url_path);
CREATE TABLE IF NOT EXISTS user_mgmt.payment_url_pool (id BIGINT PRIMARY KEY,path VARCHAR(120) NOT NULL UNIQUE,assigned_user_id UUID UNIQUE REFERENCES user_mgmt.users(id) ON DELETE SET NULL,assigned_at TIMESTAMPTZ,capacity_alert_sent BOOLEAN NOT NULL DEFAULT FALSE);

